def max_value_on_paths(N: int, grid_values: list) -> int:
    """
    Return the maximum sum of values that can be collected by two paths
    from the top-left corner to the bottom-right corner of an N×N grid.

    Each cell value can be collected at most once, even if both paths visit it.
    The grid is specified by a list of (x, y, value) tuples terminated by (0, 0, 0).
    Coordinates are 1‑based.
    """
    # Build the grid
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, v in grid_values:
        if x == 0 and y == 0 and v == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = v

    # Special case: single cell
    if N == 1:
        return grid[1][1]

    INF_NEG = -10**18

    # dp_prev[x1][x2] = best sum after step k with path1 at (x1, k-x1) and path2 at (x2, k-x2)
    dp_prev = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[1][1]  # both start at (1,1)

    # Total sum of coordinates starts at 2 (1+1). We begin from step k=3 up to k=2N
    for k in range(3, 2 * N + 1):
        dp_cur = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
        x_low = max(1, k - N)
        x_high = min(N, k - 1)

        for x1 in range(x_low, x_high + 1):
            y1 = k - x1
            if y1 < 1 or y1 > N:
                continue
            for x2 in range(x_low, x_high + 1):
                y2 = k - x2
                if y2 < 1 or y2 > N:
                    continue

                best = INF_NEG
                # Consider all combinations of previous moves
                for dx1 in (0, -1):  # 0 -> came from left (x same), -1 -> came from up (x-1)
                    prev_x1 = x1 + dx1
                    if prev_x1 < 1:
                        continue
                    for dx2 in (0, -1):
                        prev_x2 = x2 + dx2
                        if prev_x2 < 1:
                            continue
                        val = dp_prev[prev_x1][prev_x2]
                        if val > best:
                            best = val

                if best == INF_NEG:
                    continue

                # Add values for the current positions, count once if they coincide
                if x1 == x2 and y1 == y2:
                    add = grid[x1][y1]
                else:
                    add = grid[x1][y1] + grid[x2][y2]

                dp_cur[x1][x2] = best + add

        dp_prev = dp_cur

    return dp_prev[N][N]

