def find_number_combinations():
    """
    Generate all unique combinations of three numbers, each formed from the digits 1 to 9 without repetition,
    such that the second number is twice the first and the third is three times the first.

    Returns:
        list of tuples: A sorted list of tuples, where each tuple contains three integers representing
                        the valid number combinations in ascending order based on the first number.
    """
    def has_unique_valid_digits(n: int) -> bool:
        s = str(n)
        return len(s) == 3 and '0' not in s and len(set(s)) == 3

    results = []
    # Iterate over all 3-digit numbers with distinct digits from 1-9
    for d1 in range(1, 10):
        for d2 in range(1, 10):
            if d2 == d1:
                continue
            for d3 in range(1, 10):
                if d3 == d1 or d3 == d2:
                    continue
                first = d1 * 100 + d2 * 10 + d3
                # The third number must not exceed 999: 3 * first <= 999 => first <= 333
                if first > 333:
                    continue
                second = first * 2
                third = first * 3
                if not (100 <= second <= 999 and 100 <= third <= 999):
                    continue
                if has_unique_valid_digits(second) and has_unique_valid_digits(third):
                    results.append((first, second, third))
    # The loops generate numbers in ascending order of 'first'
    return results

