def max_product(num_str: str, N: int, K: int) -> int:
    """
    Computes the maximum product obtainable by inserting K multiplication signs
    into the string `num_str`, which represents a sequence of digits. Each
    multiplication sign splits the string into contiguous parts; each part
    is interpreted as an integer and all parts are multiplied together.
    The function returns the maximum possible product as a Python integer.
    Invalid inputs or impossible numbers of multiplication signs result in 0.
    """
    try:
        # Sanitize inputs
        if not isinstance(num_str, str) or not num_str.isdigit():
            return 0
        N = len(num_str)
        if K < 0 or K > N - 1:
            return 0

        # Precompute integer values for all substrings num_str[i:j] (0 <= i < j <= N)
        vals = [[0] * (N + 1) for _ in range(N)]
        for i in range(N):
            val = 0
            for j in range(i, N):
                val = val * 10 + (ord(num_str[j]) - 48)
                vals[i][j + 1] = val

        # DP table: dp[i][k] = max product for first i digits with k multiplications
        dp = [[0] * (K + 1) for _ in range(N + 1)]
        for i in range(1, N + 1):
            dp[i][0] = vals[0][i]  # single segment

        for i in range(1, N + 1):
            max_k = min(K, i - 1)
            for k in range(1, max_k + 1):
                best = 0
                # last segment starts at position j (0 <= j < i)
                for j in range(k, i):
                    product = dp[j][k - 1] * vals[j][i]
                    if product > best:
                        best = product
                dp[i][k] = best

        return dp[N][K]
    except Exception:
        return 0

