def calculate_scholarship(grades: List[int], leader: str, west: str, papers: int) -> int:
    """
    Calculate the scholarship amount based on academic performance,
    class evaluation, leadership status, region, and research output.

    Parameters:
        grades (list[int]): Two grades [final average, class evaluation].
        leader (str): 'Y' if the student is a class leader, otherwise 'N'.
        west (str): 'Y' if the student is from the western region, otherwise 'N'.
        papers (int): Number of research papers published.

    Returns:
        int: Total scholarship amount.

    Raises:
        ValueError: If input data is invalid.
    """
    # Validate grades
    if not isinstance(grades, list) or len(grades) != 2:
        raise ValueError("grades must be a list of two integers.")
    try:
        avg, eval_ = (int(g) for g in grades)
    except (TypeError, ValueError):
        raise ValueError("grades must contain integer values.")
    if not (0 <= avg <= 100 and 0 <= eval_ <= 100):
        raise ValueError("grade values must be between 0 and 100 inclusive.")

    # Validate leader and west flags
    if leader not in {'Y', 'N'}:
        raise ValueError("leader must be 'Y' or 'N'.")
    if west not in {'Y', 'N'}:
        raise ValueError("west must be 'Y' or 'N'.")

    # Validate papers
    if not isinstance(papers, int) or papers < 0:
        raise ValueError("papers must be a non‑negative integer.")

