def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    """
    Optimize the placement of aisles in a classroom to minimize the amount of chatting between students.

    Args:
    M (int): The number of rows in the classroom.
    N (int): The number of columns in the classroom.
    K (int): The number of horizontal aisles to add.
    L (int): The number of vertical aisles to add.
    D (int): The number of chatting pairs in the classroom.
    chatting_pairs (list of tuples): A list of tuples, each containing the positions (Xi, Yi) and (Pi, Qi) of a chatting pair.

    Returns:
    (str, str): Two space-separated strings representing the optimal row and column indices for the aisles.
    """
    import itertools

    # possible aisle positions (after row i or after column j)
    horiz_pos = list(range(1, M))  # 1..M-1
    vert_pos = list(range(1, N))   # 1..N-1

    # Precompute bit masks of aisle positions that would separate each pair
    pair_hrange = []
    pair_vrange = []
    for (x1, y1, x2, y2) in chatting_pairs:
        # horizontal separation
        if x1 != x2:
            low, high = min(x1, x2), max(x1, x2) - 1
            hmask = 0
            for pos in range(low, high + 1):
                hmask |= 1 << (pos - 1)
        else:
            hmask = 0

        # vertical separation
        if y1 != y2:
            low, high = min(y1, y2), max(y1, y2) - 1
            vmask = 0
            for pos in range(low, high + 1):
                vmask |= 1 << (pos - 1)
        else:
            vmask = 0

        pair_hrange.append(hmask)
        pair_vrange.append(vmask)

    # Function to create mask from a combination of positions
    def combo_mask(comb, count_positions):
        mask = 0
        for pos in comb:
            mask |= 1 << (pos - 1)
        return mask

    # generate all possible horizontal and vertical mask combinations
    H_masks = []
    V_masks = []

    if K == 0 or K > M - 1:
        H_masks.append(0)
    else:
        for comb in itertools.combinations(horiz_pos, K):
            H_masks.append(combo_mask(comb, M - 1))

    if L == 0 or L > N - 1:
        V_masks.append(0)
    else:
        for comb in itertools.combinations(vert_pos, L):
            V_masks.append(combo_mask(comb, N - 1))

    best_count = -1
    best_H = 0
    best_V = 0

    # Evaluate each combination
    for hmask in H_masks:
        for vmask in V_masks:
            count = 0
            for hseg, vseg in zip(pair_hrange, pair_vrange):
                if (hseg & hmask) or (vseg & vmask):
                    count += 1
            if count > best_count:
                best_count = count
                best_H = hmask
                best_V = vmask

    # Convert masks back to space-separated strings
    def mask_to_str(mask, count_positions):
        if count_positions == 0:
            return ''
        parts = []
        for pos in range(1, count_positions + 1):
            if mask & (1 << (pos - 1)):
                parts.append(str(pos))
        return ' '.join(parts)

    row_str = mask_to_str(best_H, M - 1)
    col_str = mask_to_str(best_V, N - 1)
    return (row_str, col_str)

