def polynomial_to_string(n: int, coeffs: list[int]) -> str:
    parts = []
    for i, coeff in enumerate(coeffs):
        deg = n - i
        if coeff == 0:
            continue
        abs_coeff = abs(coeff)

        if deg == 0:
            coeff_part = str(coeff)
        else:
            coeff_part = '' if abs_coeff == 1 else str(abs_coeff)

        if deg == 0:
            var_part = ''
        elif deg == 1:
            var_part = 'x'
        else:
            var_part = f'x^{deg}'

        term = coeff_part + var_part

        if not parts:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '+' if coeff > 0 else '-'

        parts.append(sign + term)

    return ''.join(parts) if parts else '0'

