def count_partitions(n: int, k: int, x: int) -> int:
    """
    Count the number of ways to partition an integer n into k parts,
    where each part is at least x and order of parts does not matter.

    Parameters:
    n (int): The integer to be partitioned.
    k (int): The number of parts to divide n into.
    x (int): The minimum value for each part.

    Returns:
    int: The number of distinct partitioning ways.
    """
    if k <= 0:
        return 0
    # After subtracting the minimum value from each part,
    # we need to partition the remaining amount into k nonnegative parts.
    remaining = n - k * x
    if remaining < 0:
        return 0

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def part(amount: int, max_part: int) -> int:
        """
        Number of partitions of 'amount' using parts of size at most 'max_part'.
        This is equal to the number of partitions of 'amount' into at most 'max_part'
        parts, which by conjugation is the same as partitions into at most 'max_part' parts.
        """
        if amount == 0:
            return 1  # exactly one way to partition zero (the empty partition)
        if max_part == 0 or amount < 0:
            return 0
        if max_part > amount:
            max_part = amount
        # Either we do not use a part of size 'max_part' or we use at least one.
        return part(amount, max_part - 1) + part(amount - max_part, max_part)

    return part(remaining, k)

