def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts all pairs of positive integers (P, Q) such that:
        gcd(P, Q) == x0
        lcm(P, Q) == y0

    Args:
        x0 (int): the required greatest common divisor.
        y0 (int): the required least common multiple.

    Returns:
        int: the number of valid pairs (P, Q).
    """
    # Helper to compute GCD without importing math
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return abs(a)

    # Validate inputs: must be positive integers
    if x0 <= 0 or y0 <= 0:
        return 0

    # Necessary condition: x0 divides y0
    if y0 % x0 != 0:
        return 0

    m = y0 // x0  # product of the co-prime factors a and b
    count = 0
    d = 1
    while d * d <= m:
        if m % d == 0:
            a = d
            b = m // d
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
        d += 1
    return count

