def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers reachable from the given integer `n` by applying the
    provided digit transformation rules in a breadth-first manner.

    Args:
        n (int): The original integer number.
        rules (list of tuple): Each tuple (x, y) denotes that the digit x
                               can be transformed into digit y.

    Returns:
        int: The number of unique integers that can be generated, including the original.
    """
    # Build a mapping from single-digit string to the list of possible target digits
    transform_map = {}
    for src, tgt in rules:
        src_str = str(src)
        tgt_str = str(tgt)
        transform_map.setdefault(src_str, []).append(tgt_str)

    # If there are no transformation rules, return 1 (only the original number)
    if not transform_map:
        return 1

    start_str = str(n)
    visited = {int(start_str)}
    queue = [start_str]

    while queue:
        current = queue.pop(0)  # simple FIFO queue
        # Try to replace each digit that has a corresponding rule
        for idx, digit in enumerate(current):
            if digit in transform_map:
                for tgt_digit in transform_map[digit]:
                    # If the same digit is replaced by itself, skip to avoid loops
                    if tgt_digit == digit:
                        continue
                    new_num_str = current[:idx] + tgt_digit + current[idx+1:]
                    new_num = int(new_num_str)
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num_str)

    return len(visited)

