    """
    Calculate the maximum total value of herbs that can be picked within a given time limit.

    Args:
        T (int): The total time available for picking herbs.
        M (int): The number of different herbs in the cave. (May be ignored if inconsistent with herbs length.)
        herbs (List[Tuple[int, int]]): A list of tuples, each containing the time cost and value of a herb.

    Returns:
        int: The maximum total value achievable without exceeding the time limit.
    """
    # Basic input validation
    try:
        if not isinstance(T, int) or T < 0 or not isinstance(M, int) or M < 0:
            return 0
    except Exception:
        return 0

    capacity = T
    dp = [0] * (capacity + 1)

    for time_cost, value in herbs:
        # Skip invalid tuples
        try:
            if not isinstance(time_cost, int) or not isinstance(value, int):
                continue
        except Exception:
            continue
        if time_cost < 0 or value < 0:
            continue
        if time_cost > capacity:
            continue

        for t in range(capacity, time_cost - 1, -1):
            new_val = dp[t - time_cost] + value
            if new_val > dp[t]:
                dp[t] = new_val

    return max(dp) if dp else 0

