def minimum_students_to_leave(heights):
    """
    Calculates the minimum number of students that need to leave to form a choir formation.
    A choir formation is a bitonic sequence: strictly increasing up to a peak, then strictly decreasing.
    The function returns the minimal removals needed, i.e., total students minus the longest bitonic subsequence length.

    :param heights: List[int] - list of student heights
    :return: int - minimum number of students that need to leave
    """
    if not isinstance(heights, list):
        raise ValueError("heights must be a list")
    if not heights:
        return 0
    if any(not isinstance(h, int) for h in heights):
        raise ValueError("All heights must be integers")

    n = len(heights)

    # Longest increasing subsequence (strict) ending at each position
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1

    # Longest decreasing subsequence (strict) starting at each position
    # Equivalent to longest increasing on reversed list with reversed comparison
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1

    # The longest bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = inc[i] + dec[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    return n - max_bitonic

